namespace fs=std::filesystem;
namespace MonsterStudioQt {
struct WorkbenchWindowTestAccess { static void Fit(WorkbenchWindow&w,const QRect&r){w.FitToAvailableGeometry(r);} };
struct NativePreviewWidgetTestAccess { static void FailConstruction(bool enabled){NativePreviewWidget::ownerFactoryForTesting_=enabled?std::function<std::unique_ptr<StudioPreviewHost>(HWND)>([](HWND)->std::unique_ptr<StudioPreviewHost>{throw std::runtime_error("isolated owner construction failure");}):std::function<std::unique_ptr<StudioPreviewHost>(HWND)>{};} };
}
static void Need(bool b,const char*m){if(!b)throw std::runtime_error(m);}
static void Until(const std::function<bool()>&f,int ms=10000){QElapsedTimer t;t.start();while(!f()){Need(t.elapsed()<ms,"Observable boundary timeout");QTest::qWait(10);}}
static void Close(WorkbenchWindow&w){w.close();Until([&]{return !w.isVisible();});Need(w.Preview()->IsStopped(),"Close preceded owner stop");}
int main(int argc,char**argv){QApplication app(argc,argv);app.setQuitOnLastWindowClosed(false);QTimer dismiss;QObject::connect(&dismiss,&QTimer::timeout,[]{if(auto*box=qobject_cast<QMessageBox*>(QApplication::activeModalWidget()))box->accept();});dismiss.start(10);if(argc!=3)return 2;fs::path out=QString::fromLocal8Bit(argv[1]).toStdWString(),genuine=QString::fromLocal8Bit(argv[2]).toStdWString();Need(!fs::exists(out),"Fresh runtime required");fs::create_directories(out);QJsonArray results;int passed=0,failed=0;
auto test=[&](const char*n,const std::function<void()>&f){try{f();++passed;results.append(QJsonObject{{"name",n},{"passed",true}});std::cout<<"PASS "<<n<<std::endl;}catch(const std::exception&e){++failed;results.append(QJsonObject{{"name",n},{"passed",false},{"error",e.what()}});std::cout<<"FAIL "<<n<<": "<<e.what()<<std::endl;}};
test("timing_local_timezone_matches_user_environment",[]{const std::optional<std::string> t="2026-10-24T01:02:03.004Z";auto local=QDateTime::fromString(QString::fromStdString(*t),Qt::ISODateWithMs).toLocalTime();Need(Timestamp(t).contains(local.toString("yyyy-MM-dd HH:mm:ss.zzz")),"Persisted completion is not displayed in local time");Need(Timestamp(t).contains("UTC")||Timestamp(t).contains(local.timeZoneAbbreviation()),"Timestamp has no identifiable timezone");});
test("timing_preparation_span_active_and_legacy_are_distinct",[]{V::ExecutionTiming t;t.startedUtc="2026-10-24T01:00:00.000Z";t.completedUtc="2026-10-24T01:02:00.000Z";t.activeMilliseconds=1000;t.activeTimeComplete=true;t.startedBoundary="preparation_start_v1";auto full=TimingDetails(t);Need(full.contains("0:02:00.000")&&full.contains("0:00:01"),"Span and active time conflated");t.startedBoundary.reset();auto legacy=TimingDetails(t);Need(legacy.contains(QStringLiteral("完整准备至发布跨度：未记录")),"Legacy record falsely covers preparation");t.startedBoundary="execution_start_v1";Need(TimingDetails(t).contains(QStringLiteral("执行开始（不含前置准备）")),"Execution-only provenance hidden");});
test("timing_missing_invalid_zone_less_and_backwards_unknown",[]{V::ExecutionTiming t;Need(TimingDetails(t).contains(QStringLiteral("未记录")),"Missing timing invented");for(auto text:{"invalid","2026-10-24T01:00:00.000"})Need(Timestamp(std::string(text))==QStringLiteral("未记录"),"Invalid or zoneless timestamp trusted");t.startedUtc="2026-10-24T02:00:00.000Z";t.completedUtc="2026-10-24T01:00:00.000Z";t.startedBoundary="preparation_start_v1";Need(TimingDetails(t).contains(QStringLiteral("完整准备至发布跨度：未记录")),"Backwards clock yielded fabricated span");});
test("stage_real_events_unknown_and_terminal_publication",[]{V::ExecutionSnapshot s;s.active=true;s.state=V::ExecutionState::Preparing;for(auto stage:{"Environment admission","Import video","ffprobe","extract","features","matching","mapping","undistort"}){s.stage=stage;Need(!Stage(s).isEmpty(),"Known stage disappeared");}s.stage="future-stage";Need(Stage(s)=="future-stage","Unknown real event hidden");s.state=V::ExecutionState::Training;s.stage="brush";Need(Stage(s)==QStringLiteral("训练三维场景"),"Training stage missing");s.message="Actual completion and finite Gaussian PLY validated; native retirement still required";Need(Stage(s)==QStringLiteral("确认进程退出并发布结果"),"Candidate falsely presented complete");s.active=false;s.state=V::ExecutionState::Completed;Need(Stage(s)==QStringLiteral("已完成"),"Formal completion missing");});
test("window_busy_unknown_progress_and_known_training_are_separate",[]{WorkbenchWindow w;w.show();WorkbenchState s;s.busy=true;s.status=QStringLiteral("准备中");s.stage=QStringLiteral("导入并校验视频");w.ApplyState(s);QProgressBar*stage=nullptr,*training=nullptr;for(auto*p:w.findChildren<QProgressBar*>()){if(p->accessibleName().contains(QStringLiteral("当前阶段")))stage=p;else if(p->accessibleName().contains(QStringLiteral("训练进度")))training=p;}Need(stage&&training&&stage->isVisible()&&stage->minimum()==0&&stage->maximum()==0&&!training->isVisible(),"Unknown overall progress is numeric or invisible");s.stage=QStringLiteral("训练三维场景");s.trainingPercent=23;s.trainingText="training 140 / 600";w.ApplyState(s);Need(training->isVisible()&&training->value()==23&&!stage->isVisible(),"Measured training not separated");s.busy=false;s.trainingPercent=-1;w.ApplyState(s);Need(!stage->isVisible()&&!training->isVisible(),"Idle has fake running progress");w.PermitClose();});
test("actual_window_constrained_frame_and_scroll_reachability",[]{WorkbenchWindow w;w.show();QTest::qWait(40);const QRect available(20,20,960,540);WorkbenchWindowTestAccess::Fit(w,available);QTest::qWait(60);std::cout<<"GEOMETRY available="<<available.x()<<","<<available.y()<<","<<available.width()<<","<<available.height()<<" frame="<<w.frameGeometry().x()<<","<<w.frameGeometry().y()<<","<<w.frameGeometry().width()<<","<<w.frameGeometry().height()<<" client="<<w.width()<<","<<w.height()<<" minimum="<<w.minimumWidth()<<","<<w.minimumHeight()<<std::endl;Need(available.contains(w.frameGeometry()),"Real frame does not fit injected960x540");Need(w.minimumWidth()<=960&&w.minimumHeight()<=540,"Minimum prevents fit");w.SetSuggestedTask({"movie.mp4","fixture","D:/projects",{},1});QPushButton*start=nullptr;for(auto*b:w.findChildren<QPushButton*>())if(b->text()==QStringLiteral("开始重建"))start=b;Need(start,"Primary action absent");QScrollArea*scroll=nullptr;for(auto*p=start->parentWidget();p;p=p->parentWidget())if((scroll=qobject_cast<QScrollArea*>(p)))break;if(scroll){scroll->ensureWidgetVisible(start);QTest::qWait(30);Need(scroll->viewport()->rect().intersects(QRect(start->mapTo(scroll->viewport(),QPoint()),start->size())),"Primary action unreachable on constrained actual window");}else{Need(start->isVisible()&&w.rect().contains(QRect(start->mapTo(&w,QPoint()),start->size())),"Sticky primary action clipped on constrained actual window");}w.PermitClose();});
test("native_constructor_failure_empty_retire_monotonic_retry_and_close",[]{NativePreviewWidgetTestAccess::FailConstruction(true);NativePreviewWidget v;v.show();Need(!v.StartOwner()&&v.Snapshot().state==StudioPreviewState::Failed,"Actual throwing factory did not fail startup");const auto error=v.Snapshot().error;v.Retire(8);v.Retire(3);Need(v.Snapshot().retiredToken==8&&v.Snapshot().error==error&&v.Snapshot().state==StudioPreviewState::Failed,"Empty retirement lost failure or watermark");NativePreviewWidgetTestAccess::FailConstruction(false);Need(v.StartOwner(),"Owner cannot retry after failed construction");v.Retire(9);Until([&]{return v.Snapshot().retiredToken>=9;});v.RequestStop();Until([&]{return v.IsStopped();});Need(v.Snapshot().deviceCreations==v.Snapshot().deviceDestructions,"Retry leaked Vulkan owner");});
test("controller_owner_start_failure_open_then_close_no_deadlock",[&]{NativePreviewWidgetTestAccess::FailConstruction(true);WorkbenchWindow w;WorkbenchController c(w);w.show();Until([&]{return !c.impl_->busy;});Need(!c.impl_->ownerStarted&&w.Preview()->Snapshot().state==StudioPreviewState::Failed,"Controller did not observe startup failure");w.openProjectRequested(QString::fromStdWString(genuine.wstring()));Until([&]{return !c.impl_->busy&&!c.impl_->pendingRetire;});Need(c.impl_->state.projectPath.size()>0,"Open stuck at impossible retirement");Close(w);NativePreviewWidgetTestAccess::FailConstruction(false);});
test("navigation_current_noncompletion_final_boundary_matrix",[&]{auto q=V::ReconstructionQueue::OpenForInspection(genuine);V::ProjectReconstruction service(*q,{});auto real=service.Inspect();Need(Viewable(real),"Read-only genuine success unavailable");WorkbenchWindow w;WorkbenchController c(w);w.show();Until([&]{return !c.impl_->busy;});auto&impl=*c.impl_;impl.state.projectPath=QString::fromStdWString(genuine.wstring());for(auto op:{WorkbenchController::Impl::Op::Start,WorkbenchController::Impl::Op::Resume})for(auto state:{V::ExecutionState::Paused,V::ExecutionState::Failed,V::ExecutionState::Stopped}){w.ShowWorkbench();WorkbenchController::Impl::Event e;e.command.op=op;e.command.generation=impl.generation;e.command.execution="new-current";e.selected=real;e.latest=real;e.latest->executionId="new-current";e.latest->state=state;impl.latest=*e.latest;impl.observedExecution="new-current";auto request=impl.requestId;impl.LoadResult(e);Need(impl.requestId==request&&w.findChild<QStackedWidget*>()->currentIndex()==0,"Start/Resume noncompletion navigated older genuine success");}Close(w);});
test("navigation_stale_generation_and_changed_result_rejected",[&]{auto q=V::ReconstructionQueue::OpenForInspection(genuine);V::ProjectReconstruction service(*q,{});auto real=service.Inspect();WorkbenchWindow w;WorkbenchController c(w);w.show();Until([&]{return !c.impl_->busy;});auto&impl=*c.impl_;impl.latest=real;impl.observedExecution=real.executionId;WorkbenchController::Impl::Event e;e.command.op=WorkbenchController::Impl::Op::Start;e.command.generation=impl.generation-1;e.latest=real;e.selected=real;auto request=impl.requestId;impl.LoadResult(e);Need(impl.requestId==request,"Stale generation navigated");e.command.generation=impl.generation;e.selected->outputSha256=std::string(64,'0');impl.LoadResult(e);Need(impl.requestId==request,"Changed output identity navigated");Close(w);});
QFile f(QString::fromStdWString((out/"test-results.json").wstring()));Need(f.open(QIODevice::WriteOnly),"Result write");f.write(QJsonDocument(QJsonObject{{"passed",passed},{"failed",failed},{"tests",results}}).toJson());std::cout<<"SUMMARY "<<passed<<" passed "<<failed<<" failed"<<std::endl;return failed?1:0;}


